// Anchor returns the start of a subscription's first paid period: the end of its trial when it started with one, and its
// start otherwise. Its billing periods are counted from the anchor.
func Anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return sub.TrialEnd.UTC()
	}
	return sub.StartedAt.UTC()
}

// PeriodStart returns the start of period n (n = 0, 1, 2, ...) of a plan billed at iv, counted from anchor. Period n starts
// n months (or years) after the anchor, on the anchor's day of the month at its time of day, or on the month's last day
// when that month is shorter. Counting from the anchor each time, rather than from the previous period, keeps a short
// month from moving the later periods. Times are UTC.
func PeriodStart(anchor time.Time, iv store.Interval, n int) time.Time {
	a := anchor.UTC()
	months := n
	if iv == store.Yearly {
		months = 12 * n
	}
	first := time.Date(a.Year(), a.Month()+time.Month(months), 1, 0, 0, 0, 0, time.UTC)
	lastDay := first.AddDate(0, 1, -1).Day()
