func TestRenewCatchesUpEveryMissedPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// The renewal job did not run for two months.
	e.Clock.Set(time.Date(2026, 4, 15, 10, 0, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) ||
		!got.CurrentPeriodEnd.Equal(time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("after the catch-up = %+v", got)
	}
	// Each of the three periods since January 31 has its own invoice: the first from Create, then one per missed period.
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 {
		t.Fatalf("invoices = %d, want 3", len(invs))
	}
	for _, want := range [][2]time.Time{
		{time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)},
	} {
		found := false
		for _, inv := range invs {
			found = found || (inv.PeriodStart != nil && inv.PeriodEnd != nil && inv.PeriodStart.Equal(want[0]) && inv.PeriodEnd.Equal(want[1]))
		}
		if !found {
			t.Errorf("no invoice for the period %v to %v in %+v", want[0], want[1], invs)
		}
	}
	if cs := e.Gateway.Charges(); len(cs) != 3 {
		t.Fatalf("charges = %d, want 3", len(cs))
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed again with nothing due: %d", n)
	}
}

