117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise each period that has ended is followed by the next one, in order, and each
145	// new period is invoiced: a licensed plan bills the new period in advance, a metered plan bills the usage of the period that
146	// ended. A declined charge makes the subscription past due. RenewDue returns how many subscriptions it renewed or canceled.
147	func (s *Service) RenewDue(ctx context.Context) (int, error) {
148		now := s.Clock.Now()
149		n := 0
150		for _, sub := range s.Store.DueSubscriptions(now) {
151			if err := ctx.Err(); err != nil {
152				return n, err
153			}
154			if err := s.renew(ctx, sub, now); err != nil {
155				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
156			}
157			n++
158		}
159		return n, nil
160	}
161	
162	// renew moves a subscription forward one period at a time, from the end of its current period, until its current period
163	// has not ended by now. Each period it moves to is invoiced on its own, so several missed periods make several invoices,
164	// in order. The boundaries come from the subscription's anchor, so they do not depend on when the job ran.
165	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
166		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
167		if !ok {
168			return store.ErrNotFound
169		}
170		anchor := billing.Anchor(sub)
171		declined := false
172		for !sub.CurrentPeriodEnd.After(now) {
173			if sub.CancelAtPeriodEnd {
174				end := sub.CurrentPeriodEnd
175				canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
176					x.Status, x.CanceledAt = store.Canceled, &end
177					return nil
178				})
179				if err == nil {
180					s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
181				}
182				return err
183			}
184			start := sub.CurrentPeriodEnd
185			end := billing.PeriodStart(anchor, plan.Interval, billing.PeriodIndex(anchor, plan.Interval, start)+1)
186			paid := true
187			var err error
188			switch {
189			case plan.UsageType == store.Metered && sub.Status != store.Trialing:
190				paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
191			case plan.UsageType == store.Licensed:
192				paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
193			}
194			if err != nil {
195				return err
196			}
197			declined = declined || !paid
198			sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
199				x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
200				if declined {
201					x.Status = store.PastDue
202				} else {
203					x.Status = store.Active
204				}
205				return nil
206			})
207			if err != nil {
208				return err
209			}
210			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
211		}
212		return nil
213	}
214	
215	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
216	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
217	// payment method stays open and counts as paid here (it is paid by hand).
218	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
219		var lines []store.Line
220		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
221		switch plan.UsageType {
222		case store.Licensed:
223			if plan.UnitAmount > 0 {
224				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
225			}
226		case store.Metered:
227			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
228				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
229			}
230		}
231		ps, pe := start, end
232		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
233			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
234		if err != nil {
235			return false, err
236		}
237		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
238		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
239		var decline *payments.DeclineError
240		switch {
241		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
242			return true, nil
243		case errors.As(err, &decline):
244			return false, nil
245		default:
246			return false, err
247		}
248	}
249	
250	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
251		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
252			x.Status = st
253			return nil
254		})
255		if err == nil {
256			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
257		}
258		return sub, err
259	}
260	
261	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
262		if s.Publisher != nil {
263			_ = s.Publisher.Publish(ctx, orgID, typ, data)
264		}
265	}
